from collections import deque
def comps(grid):
    H,W=len(grid),len(grid[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if not seen[r][c] and grid[r][c]!=3:
                col=grid[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dr,b+dc
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and grid[na][nb]==col:
                            seen[na][nb]=True; q.append((na,nb))
                out.append(cells)
    return out
