    pat=[[i_[top+a][left+b] for b in range(ow)] for a in range(oh)]
    objcols=set(i_[p[0]][p[1]] for p in big)
    singles=[(r,c,i_[r][c]) for r in range(H) for c in range(W)
             if i_[r][c]!=bg and sum(1 for da,db in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+da<H and 0<=c+db<W and i_[r+da][c+db]==i_[r][c])==0
