    def put(o):
        for a in range(oh):
            for b in range(ow):
                out[o[0]+a][o[1]+b]=pat[a][b]
    placed={(r_,c_) for r_ in [top] for c_ in [left]}
    # greedy: candidate origins where copy contains a singleton and does not overlap already-placed or original, tie-break min |marker-center| then ... try all orders
